fn fingerprint_integer(value:Int)->Int{return __hash_key__::<Int>(value);}
fn fingerprint_flag(value:Bool)->Int{return __hash_key__::<Bool>(value);}
fn fingerprint_letter(value:Char)->Int{return __hash_key__::<Char>(value);}
fn fingerprint_text(value:Str)->Int{return __hash_key__::<Str>(value);}
fn fingerprint_nested(value:Tuple<Int,Tuple<Str,Bool>,Char>)->Int{return __hash_key__::<Tuple<Int,Tuple<Str,Bool>,Char>>(value);}
wt fingerprint_integer(0);
wt fingerprint_integer(-1);
wt fingerprint_integer(-9223372036854775808);
wt fingerprint_integer(9223372036854775807);
wt fingerprint_flag(false);
wt fingerprint_flag(true);
wt fingerprint_letter('a');
wt fingerprint_letter('z');
wt fingerprint_text("");
wt fingerprint_text("abc");
wt fingerprint_text("hash-key-value");
wt fingerprint_nested((1,("abc",true),'z'));
wt fingerprint_nested((-1,("",false),'a'));
